// Normalize the BigQuery result into a header row + string matrix.
// Headers are derived from the query result, so adding or removing columns in
// the SQL requires no change here or in any downstream node.

const rows = $input.all()
  .map((item) => item.json || {})
  .filter((row) => Object.keys(row).length > 0);

const toText = (value) => {
  if (value === null || value === undefined) return '';
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
};

if (rows.length === 0) {
  return [{
    json: {
      row_count: 0,
      column_count: 0,
      columns: [],
      records: [],
      snapshot_date: '',
      manager_count: 0,
    },
  }];
}

// Union of keys across all rows, preserving BigQuery's column order.
const columns = [];
for (const row of rows) {
  for (const key of Object.keys(row)) {
    if (!columns.includes(key)) columns.push(key);
  }
}

const idColumn = columns.includes('Employee ID') ? 'Employee ID' : null;
const seen = new Set();
const records = [];
const managers = new Set();

for (const row of rows) {
  const dedupeKey = idColumn ? toText(row[idColumn]) : JSON.stringify(row);
  if (dedupeKey !== '' && seen.has(dedupeKey)) continue;
  seen.add(dedupeKey);
  records.push(columns.map((column) => toText(row[column])));
  const managerId = toText(row['Manager ID']);
  if (managerId !== '') managers.add(managerId);
}

return [{
  json: {
    row_count: records.length,
    column_count: columns.length,
    columns,
    records,
    manager_count: managers.size,
    snapshot_date: toText(rows[0]['Snapshot Date']),
  },
}];

// Build one values:batchUpdate body per chunk of rows.
// Chunking keeps each HTTP payload well inside the Google Sheets request-size
// limit for a roster of any realistic size, while staying far below the
// 60 write-requests-per-minute-per-user quota.

const TAB_NAME = 'Sheet1';
const CHUNK_ROWS = 5000;

const source = $('Code - Normalize Roster').first().json;
const columns = source.columns || [];
const records = source.records || [];

const allRows = [columns, ...records];
const chunks = [];

for (let offset = 0; offset < allRows.length; offset += CHUNK_ROWS) {
  const slice = allRows.slice(offset, offset + CHUNK_ROWS);
  const startRow = offset + 1; // A1 notation is 1-indexed
  chunks.push({
    json: {
      chunk_index: chunks.length + 1,
      chunk_rows: slice.length,
      start_row: startRow,
      request_body: {
        valueInputOption: 'RAW',
        data: [{
          range: `${TAB_NAME}!A${startRow}`,
          majorDimension: 'ROWS',
          values: slice,
        }],
      },
    },
  });
}

return chunks.map((chunk) => ({
  json: {
    ...chunk.json,
    chunk_total: chunks.length,
  },
}));

const source = $('Code - Normalize Roster').first().json;
const chunks = $('Code - Build Sheets Write Chunks').all();

return [{
  json: {
    status: 'SUCCESS',
    spreadsheet_id: '1w-PBwKVwLoqQ7tF22baZFKAvb-Gn6f29Brwv1OdIPf4',
    spreadsheet_name: 'Org Broswer N8N Refresh Mondays',
    tab_name: 'Sheet1',
    employee_row_count: source.row_count,
    distinct_manager_count: source.manager_count,
    column_count: source.column_count,
    columns_written: source.columns,
    snapshot_date: source.snapshot_date,
    snapshot_age_days: source.snapshot_date
      ? Math.round((Date.now() - Date.parse(source.snapshot_date)) / 86400000)
      : null,
    sheets_write_requests_used: chunks.length + 1,
    schedule: 'Mondays 04:00 America/Phoenix (Arizona, no DST) = 11:00 UTC',
  },
}];

// Turn the diagnostic rows into a single actionable error message.
const rows = $input.all()
  .map((item) => item.json || {})
  .filter((row) => Object.keys(row).length > 0);

const L = [];
L.push('ROSTER REFRESH ABORTED - BigQuery returned zero rows.');
L.push('The Google Sheet was NOT cleared. The previous roster is intact.');
L.push('');

if (rows.length === 0) {
  L.push('DIAGNOSIS: the source table has NO rows at all in the last 400 days.');
  L.push('');
  L.push('That means this table is no longer being populated, or the BigQuery');
  L.push('credential has lost access to it.');
  L.push('  Table: wf-gcp-us-ae-cs-prod.cs_reporting.tbl_customer_service_employee_performance_manager');
  L.push('');
  L.push('NEXT STEP: confirm the table is still maintained. If it was retired,');
  L.push('the likely replacement is:');
  L.push('  wf-gcp-us-ae-gat-prod.ops_reporting_layer.vw_customer_service_master_reporting');
  L.push('  (employee_id, employee_name, employee_workgroup_name, employee_working_team, ...)');
} else {
  const day = rows.find((r) => String(r.datetype_value).toLowerCase() === 'day');
  L.push('The table DOES have data. Breakdown by datetype over the last 400 days:');
  L.push('');
  for (const r of rows) {
    L.push(`  datetype="${r.datetype_value}" | rows=${r.row_count} | employees=${r.distinct_employees} | ` +
           `dates ${r.min_date} -> ${r.max_date} | ${r.days_since_last_snapshot}d stale | active=${r.active_rows}`);
  }
  L.push('');
  if (!day) {
    L.push('DIAGNOSIS: no rows with datetype="Day". The roster query filters on it.');
    L.push('NEXT STEP: change the datetype filter to one of the values listed above.');
  } else if (Number(day.days_since_last_snapshot) > 30) {
    L.push(`DIAGNOSIS: the newest "Day" snapshot is ${day.days_since_last_snapshot} days old ` +
           '(${day.max_date}), outside the 30-day window the roster query allows.');
    L.push('The window is deliberately narrow so stale data is never published as current.');
    L.push('NEXT STEP: fix the upstream pipeline, or - if this table was retired - repoint');
    L.push('the query at the current source. Widening the window would publish stale data.');
  } else if (Number(day.active_rows) === 0) {
    L.push('DIAGNOSIS: "Day" rows exist and are fresh, but ZERO have stillatwayfair = TRUE.');
    L.push('NEXT STEP: the active-employee flag is not being set. Either fix upstream or');
    L.push('drop "AND t.stillatwayfair IS TRUE" from the roster query to load everyone.');
  } else {
    L.push('DIAGNOSIS: fresh, active "Day" rows exist, so the date/datetype/active filters');
    L.push('are not the cause. The remaining difference is the QUALIFY dedupe or the');
    L.push('exact-match on the snapshot date.');
    L.push(`NEXT STEP: run the roster query with "AND t.date = DATE '${day.max_date}'"`);
    L.push('substituted for the latest_snapshot CROSS JOIN and compare.');
  }
}

return [{ json: { diagnosis: L.join('\n'), diagnostic_rows: rows } }];
